            case "dha":
                return "DH Attacker";

			case "heal":
			case "h":
				return "Healer";

			case "lh":
				return "Leech Healer";

            case "dh2":
            case "2h":
			case "dh2h":
                return "DH 2nd Healer";

            case "dhh":
            case "dh":
            case "mh":
                return "DH Main Healer";

			case "def":
